#!/usr/bin/env python3
"""Eureka Nexus 2.1 — static bilingual website generator. No network calls/dependencies."""
from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).resolve().parent.parent
PAGES=['index','eureka-ai','mundo-digital','compute-node','desenvolvimento','investidores','futura-moeda','contactos','privacidade','termos']
SITE='https://eurekanexus.pt'
EMAIL='official@eurekanexus.pt'
SOCIAL={'GitHub':'https://github.com/Eureka-Nexus','X':'https://x.com/Eurekanexus','Reddit':'https://www.reddit.com/user/eurekanexus/'}
def t(lang,pt,en):return en if lang=='en' else pt
def esc(x):return escape(str(x),quote=True)
def url(page,lang):
    dest='' if page=='index' else page+'.html'
    return ('/en/' if lang=='en' else '/')+dest
def eyebrow(x):return f'<div class="eyebrow">{x}</div>'
def para(x,klass=''):return f'<p{f" class={chr(34)+klass+chr(34)}" if klass else ""}>{x}</p>'
def btn(text,target,secondary=False):return f'<a class="btn{" secondary" if secondary else ""}" href="{esc(target)}">{text} <span aria-hidden="true">↗</span></a>'
def pills(items):return '<div class="chips">'+''.join(f'<span class="chip">{x}</span>' for x in items)+'</div>'
def cards(items,cols=''):
    return '<div class="grid '+cols+'">'+''.join(f'<article class="panel"><span class="num">{i:02d}</span><h3>{title}</h3><p>{body}</p>{f"<div class=detail>{extra}</div>" if extra else ""}</article>' for i,(title,body,extra) in enumerate(items,1))+'</div>'
def links_cards(items):
    return '<div class="grid">'+''.join(f'<a class="panel card-link" href="{path}"><div class="icon-symbol">{icon}</div><h3>{title}</h3><p>{body}</p></a>' for path,icon,title,body in items)+'</div>'
def faq(items):return '<div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div>'
def section(id,title,lead,inner='',label='',alt=False):
    return f'<section class="section{" alt" if alt else ""}" id="{id}"><div class="wrap"><div class="section-header">{eyebrow(label) if label else ""}<h2>{title}</h2>{para(lead) if lead else ""}</div>{inner}</div></section>'
def pagehero(lang,key,kicker,title,desc,chips=None):
    return f'<div class="wrap"><div class="breadcrumbs"><a href="{url("index",lang)}">{t(lang,"Início","Home")}</a><span>›</span><span>{t(lang,*NAV.get(key,("Privacidade","Privacy") if key=="privacidade" else ("Condições","Terms")))}</span></div></div><section class="page-hero"><div class="wrap">{eyebrow(kicker)}<h1>{title}</h1>{para(desc,"lead")}{pills(chips) if chips else ""}</div></section>'
NAV={
 'index':('Início','Home'),'eureka-ai':('Eureka AI','Eureka AI'),
 'mundo-digital':('Mundo Digital','Digital World'),'compute-node':('Compute Node','Compute Node'),
 'desenvolvimento':('Desenvolvimento','Development'),'investidores':('Investidores','Investors'),
 'futura-moeda':('Moeda futura','Future Token'),'contactos':('Contactos','Contact')}
META={
'index':(('Eureka Nexus — O futuro da inteligência digital','Eureka Nexus — The Future of Digital Intelligence'),('Eureka AI, identidade digital pessoal, mundo digital e a futura Eureka Compute Network. Conhece a visão, o desenvolvimento e as oportunidades para contribuir.','Eureka AI, personal digital identity, a connected digital world and the planned Eureka Compute Network. Explore the vision and contribute.')),
'eureka-ai':(('Eureka AI — A tua própria identidade digital','Eureka AI — Your Own Digital Identity'),('Descobre a visão Eureka AI: chat, voz, visão, memória, personalidade, tarefas, aprendizagem e uma Eureka única para cada pessoa.','Discover Eureka AI: chat, voice, vision, memory, personality, tasks, learning and a unique Eureka for each person.')),
'mundo-digital':(('O Mundo Digital da Eureka','The Eureka Digital World'),('Um mundo digital privado e conectado: espaços, identidades digitais, colaboração entre pessoas e agentes, com controlo e privacidade.','A private and connected digital world: spaces, digital identities, people and agents collaborating with control and privacy.')),
'compute-node':(('Eureka Compute Node — Computação para IA','Eureka Compute Node — Computing for AI'),('Futura rede de GPUs e CPUs a executar tarefas reais e validadas de IA. Contribuições, segurança, métricas e recompensas planeadas.','A future CPU/GPU network running genuine, verified AI tasks. Contributions, security, metrics and planned rewards.')),
'desenvolvimento':(('Desenvolvimento Eureka AI — Progresso e demonstrações','Eureka AI Development — Progress and Demos'),('Acompanha o desenvolvimento da Eureka AI, o roadmap técnico e futuras capturas e vídeos reais da aplicação.','Follow Eureka AI development, technical milestones and forthcoming real application screenshots and videos.')),
'investidores':(('Investidores e Parcerias — Eureka Nexus','Investors and Partnerships — Eureka Nexus'),('Regista o teu interesse em acompanhar e investir no desenvolvimento futuro da Eureka AI e da Compute Network.','Express your interest in future investment and partnerships with Eureka AI and the Compute Network.')),
'futura-moeda':(('Moeda futura e recompensas — Eureka Network','Future Token and Rewards — Eureka Network'),('Conhece a proposta de recompensas dos contribuidores CPU/GPU, emissão controlada, pré-venda futura e regras ainda em estudo.','Explore proposed CPU/GPU contribution rewards, controlled issuance, a future presale and draft economic rules.')),
'contactos':(('Contactos e Comunidade — Eureka Nexus','Contact and Community — Eureka Nexus'),('Contacta o projeto Eureka Nexus, acompanha GitHub e as redes sociais oficiais.','Contact Eureka Nexus and follow its official GitHub and social channels.')),
'privacidade':(('Privacidade — Eureka Nexus','Privacy — Eureka Nexus'),('Informação provisória de privacidade do site informativo Eureka Nexus.','Provisional privacy information for the Eureka Nexus informational website.')),
'termos':(('Condições — Eureka Nexus','Terms — Eureka Nexus'),('Condições gerais do site e limitações de disponibilidade dos serviços em desenvolvimento.','General website terms and development-stage service limitations.'))}
def header(lang,active):
    nav=''.join(f'<a href="{url(k,lang)}"{" aria-current=page" if k==active else ""}>{t(lang,*pair)}</a>' for k,pair in NAV.items())
    return f'''<a class="skip" href="#main">{t(lang,'Saltar para o conteúdo','Skip to content')}</a><header class="header"><div class="wrap header-inner"><a class="brand" href="{url('index',lang)}"><img src="{'../' if lang=='en' else ''}assets/mark.svg" alt=""><span>EUREKA NEXUS<small>DIGITAL INTELLIGENCE · PORTUGAL</small></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="site-nav" aria-label="{t(lang,'Abrir ou fechar menu','Toggle menu')}" data-menu-toggle>☰</button><nav class="nav" id="site-nav" aria-label="{t(lang,'Navegação principal','Main navigation')}" data-nav>{nav}</nav><div class="langs" aria-label="Language"><a href="{url(active,'pt')}" hreflang="pt-PT"{' aria-current=true' if lang=='pt' else ''}>PT</a><a href="{url(active,'en')}" hreflang="en"{' aria-current=true' if lang=='en' else ''}>EN</a></div></div></header>'''
def footer(lang):
    section1=''.join(f'<a href="{url(k,lang)}">{t(lang,*NAV[k])}</a>' for k in ['eureka-ai','mundo-digital','compute-node','desenvolvimento'])
    section2=''.join(f'<a href="{url(k,lang)}">{t(lang,*NAV[k])}</a>' for k in ['investidores','futura-moeda','contactos'])
    section3=''.join(f'<a href="{u}" target="_blank" rel="noopener noreferrer">{n} ↗</a>' for n,u in SOCIAL.items())
    return f'''<footer class="foot"><div class="wrap"><div class="foot-grid"><div class="foot-brand"><div class="brand"><img src="{'../' if lang=='en' else ''}assets/mark.svg" alt=""><span>EUREKA NEXUS<small>BEYOND THE INTERFACE</small></span></div><p>{t(lang,'Estamos a construir uma inteligência digital com memória, conhecimento e presença — para um futuro em que cada pessoa possa ter a sua própria Eureka.','We are building digital intelligence with memory, knowledge and presence — towards a future where each person can have their own Eureka.')}</p><p class="small">{t(lang,'Projeto português · Em desenvolvimento','Portuguese project · In development')}</p></div><div><h4>{t(lang,'Explorar','Explore')}</h4>{section1}</div><div><h4>{t(lang,'Participar','Get involved')}</h4>{section2}</div><div><h4>{t(lang,'Comunidade','Community')}</h4>{section3}<a href="mailto:{EMAIL}">{EMAIL}</a></div></div><div class="foot-bottom"><span>© 2026 Eureka Nexus · {t(lang,'Investigação e desenvolvimento','Research and development')}</span><div><a href="{url('privacidade',lang)}">{t(lang,'Privacidade','Privacy')}</a> · <a href="{url('termos',lang)}">{t(lang,'Condições','Terms')}</a></div><span>{t(lang,'Funcionalidades futuras sujeitas a testes e validação','Future features subject to testing and validation')}</span></div></div></footer>'''
def document(lang,key,body):
    title=t(lang,*META[key][0]);desc=t(lang,*META[key][1]); canonical=SITE+url(key,lang);prefix='../' if lang=='en' else ''
    org={"@context":"https://schema.org","@type":"Organization","name":"Eureka Nexus","url":SITE,"logo":SITE+'/assets/mark.svg',"sameAs":list(SOCIAL.values())}
    return f'''<!doctype html><html lang="{ 'en' if lang=='en' else 'pt-PT'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#060d18"><meta name="description" content="{esc(desc)}"><meta property="og:type" content="website"><meta property="og:site_name" content="Eureka Nexus"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{SITE}/assets/og.svg"><meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="pt-PT" href="{SITE+url(key,'pt')}"><link rel="alternate" hreflang="en" href="{SITE+url(key,'en')}"><link rel="alternate" hreflang="x-default" href="{SITE+url(key,'pt')}"><link rel="icon" type="image/svg+xml" href="{prefix}assets/mark.svg"><link rel="stylesheet" href="{prefix}assets/site.css"><title>{esc(title)}</title><script type="application/ld+json">{json.dumps(org,ensure_ascii=False,separators=(',',':'))}</script><script src="{prefix}assets/site.js" defer></script></head><body>{header(lang,key)}<main id="main">{body}</main>{footer(lang)}</body></html>'''
